// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function testFuzz_property(uint256 amount, bytes calldata data) public {
        vm.assume(amount <= 1 ether);
        uint256 before = c.depositsCount();
        vm.deal(address(c), 1 ether);
        address target = address(0xBEEF);
        c.sendMoney(target, amount, data);
        assertTrue(c.depositsCount() == before);
    }
}
